#!/usr/bin/env bash
# scripts/check-templ-header.sh — every committed *_templ.go file's
# `// templ: version:` header must match the templ version in go.mod.
#
# Born from the 2026-11-13 done-prompt window (report §e5/§d5): the host
# PATH templ binary (v0.3.1123) skews against go.mod's v0.3.1100, so a
# `templ generate` run outside the nix shell plants 1123 headers into
# generated files while the flake's templCliOverride (single source,
# flake.nix) pins 0.3.1100. This gate catches that drift at HEAD instead
# of at the nix freshness oracle, deep inside a build.
#
# Scope: every tracked *_templ.go plus go.mod's github.com/a-h/templ line.
#
# --self-test pins the summary line + a negative-path battery via the
# TQ_TEMPL_HEADER_SCOPE hook (fleet convention).
set -euo pipefail
cd "$(dirname "$0")/.."

self_abs="$(cd "$(dirname "$0")" && pwd)/$(basename "$0")"

if [ "${1:-}" = "--self-test" ]; then
	set -euo pipefail
	tmp="$(mktemp -d)"
	trap 'rm -rf "$tmp"' EXIT

	go_mod="$tmp/go.mod"
	printf 'module example.com/x\n\ngo 1.26\n\nrequire github.com/a-h/templ v0.3.1100\n' >"$go_mod"

	# positive: header matches go.mod
	printf '// Code generated by templ - DO NOT EDIT.\n\n// templ: version: v0.3.1100\n\npackage w\n' >"$tmp/good_templ.go"
	# negative 1: skewed header (the incident shape: host 1123 over go.mod 1100)
	printf '// templ: version: v0.3.1123\n\npackage w\n' >"$tmp/skewed_templ.go"
	# negative 2: header missing entirely
	printf 'package w\n' >"$tmp/noheader_templ.go"

	out="$(TQ_TEMPL_HEADER_SCOPE="$tmp/*_templ.go" TQ_TEMPL_HEADER_GOMOD="$go_mod" "$self_abs" 2>&1)" && rc=0 || rc=$?
	[ "$rc" -eq 1 ] || {
		echo "templ-header self-test FAIL: negative battery rc=$rc (want 1): $out"
		exit 1
	}
	for shape in "$tmp/skewed_templ.go" "$tmp/noheader_templ.go"; do
		grep -qF "$shape" <<<"$out" || {
			echo "templ-header self-test FAIL: output does not name $shape: $out"
			exit 1
		}
	done
	grep -qF "1 templ header ok / 3 checked" <<<"$out" || {
		echo "templ-header self-test FAIL: summary shape wrong: $out"
		exit 1
	}

	out="$(TQ_TEMPL_HEADER_SCOPE="$tmp/good_templ.go" TQ_TEMPL_HEADER_GOMOD="$go_mod" "$self_abs" 2>&1)" && rc=0 || rc=$?
	[ "$rc" -eq 0 ] || {
		echo "templ-header self-test FAIL: positive battery rc=$rc (want 0): $out"
		exit 1
	}
	grep -qF "1 templ header ok / 1 checked" <<<"$out" || {
		echo "templ-header self-test FAIL: positive summary shape wrong: $out"
		exit 1
	}

	echo "templ-header self-test ok"
	exit 0
fi

scope="${TQ_TEMPL_HEADER_SCOPE:-}"
gomod="${TQ_TEMPL_HEADER_GOMOD:-go.mod}"

if [ -z "$scope" ]; then
	scope="$(git ls-files '*_templ.go' | tr '\n' ' ')"
	[ -n "$(printf '%s' "$scope" | tr -d '[:space:]')" ] || {
		echo "templ-header: no tracked *_templ.go files found"
		exit 1
	}
fi

want="$(sed -n 's/^require github.com\/a-h\/templ \(v[0-9.]*\)$/\1/p; s/	github.com\/a-h\/templ \(v[0-9.]*\).*$/\1/p' "$gomod" | head -1)"
if [ -z "$want" ]; then
	echo "templ-header FAIL: no github.com/a-h/templ version found in $gomod"
	exit 1
fi

ok=0
fail=0
for f in $scope; do
	header="$(sed -n 's|^// templ: version: \(v[0-9.]*\)$|\1|p' "$f" | head -1)"
	if [ -z "$header" ]; then
		echo "templ-header FAIL: $f has no '// templ: version:' header (generated by templ ≥ 0.3.x only)"
		fail=$((fail + 1))
	elif [ "$header" != "$want" ]; then
		echo "templ-header FAIL: $f header $header != go.mod templ $want — regenerate inside the nix shell (templCliOverride)"
		fail=$((fail + 1))
	else
		ok=$((ok + 1))
	fi
done

echo "$ok templ header ok / $((ok + fail)) checked"
[ "$fail" -eq 0 ]
